INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (1349, 'original', 'nav-due-west', 'Navigation', NULL, 'multiple', 'On a compass, what bearing is due West?', '270°', '["90°","180°","360°"]', 'Bearings go clockwise from North: N 0°, E 90°, S 180°, W 270°.', 'approved', '2026-11-19 00:55:17');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (1350, 'original', 'nav-southeast', 'Navigation', NULL, 'multiple', 'What bearing is Southeast?', '135°', '["45°","225°","315°"]', 'Southeast is halfway between East (90°) and South (180°).', 'approved', '2026-11-19 00:55:17');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (1351, 'original', 'nav-declination', 'Navigation', NULL, 'multiple', 'The angle between magnetic north and true north is called…', 'Declination', '["Azimuth","Latitude","Parallax"]', 'Declination changes by location. Maps list it so you can correct your compass reading.', 'approved', '2026-11-19 00:55:17');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (1352, 'original', 'nav-sunrise', 'Navigation', NULL, 'multiple', 'Roughly which direction does the sun rise?', 'East', '["West","North","South"]', 'It rises roughly east and sets roughly west, drifting north or south of due east with the seasons.', 'approved', '2026-11-19 00:55:17');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (1353, 'original', 'nav-parallels', 'Navigation', NULL, 'multiple', 'Lines of latitude are also called…', 'Parallels', '["Meridians","Bearings","Contours"]', 'Latitude lines run parallel to the equator. Longitude lines (meridians) run pole to pole.', 'approved', '2026-11-19 00:55:17');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (1354, 'original', 'nav-full-turn', 'Navigation', NULL, 'multiple', 'How many degrees are in a full turn on a compass?', '360°', '["180°","270°","100°"]', 'A full circle is 360°, so North is both 0° and 360°.', 'approved', '2026-11-19 00:55:17');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (1355, 'original', 'nav-right-turn', 'Navigation', NULL, 'multiple', 'You''re heading North (0°) and turn 90° to the right. What''s your new bearing?', '90°', '["270°","180°","45°"]', 'Bearings increase clockwise, so a right turn adds: 0° + 90° = 90° (East).', 'approved', '2026-11-19 00:55:17');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (1356, 'original', 'diy-345', 'Home & DIY', NULL, 'multiple', 'To check a corner is square, you mark 3 ft on one wall and 4 ft on the other. The diagonal should be…', '5 ft', '["6 ft","7 ft","4½ ft"]', '3² + 4² = 5² (9 + 16 = 25). A 5 ft diagonal means a true 90° corner. This is the 3-4-5 rule.', 'approved', '2026-11-19 00:55:17');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (1357, 'original', 'diy-equal-diagonals', 'Home & DIY', NULL, 'multiple', 'A four-sided frame with equal opposite sides is perfectly square at the corners when its diagonals are…', 'Equal length', '["Different lengths","Half the perimeter","Shorter than the sides"]', 'Measure corner to corner both ways. Equal diagonals mean a true rectangle, the standard check for decks and foundations.', 'approved', '2026-11-19 00:55:17');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (1358, 'original', 'diy-roof-pitch', 'Home & DIY', NULL, 'multiple', 'A "6 in 12" roof pitch rises 6 inches for every…', '12 inches across', '["12 feet across","12 inches of rafter","12 degrees"]', 'Pitch is rise over run: 6 in. up for every 12 in. of horizontal distance.', 'approved', '2026-11-19 00:55:17');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (1359, 'original', 'diy-sq-yard', 'Home & DIY', NULL, 'multiple', 'How many square feet are in one square yard?', '9', '["3","6","12"]', 'A yard is 3 ft, so a square yard is 3 × 3 = 9 sq ft. Handy for carpet, sod, and gravel.', 'approved', '2026-11-19 00:55:17');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (1360, 'original', 'diy-paint-coverage', 'Home & DIY', NULL, 'multiple', 'One gallon of paint covers roughly how many square feet?', '350–400', '["100–150","800–1,000","50–75"]', 'Most labels say about 350–400 sq ft per coat. Plan on two coats for a big color change.', 'approved', '2026-11-19 00:55:17');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (1361, 'original', 'diy-stud-spacing', 'Home & DIY', NULL, 'multiple', 'In most US homes, wall studs are spaced how far apart, center to center?', '16 inches', '["12 inches","20 inches","30 inches"]', '16 in. on center is the standard. 24 in. also shows up in some newer construction.', 'approved', '2026-11-19 00:55:17');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (1362, 'original', 'diy-triangle-sum', 'Home & DIY', NULL, 'multiple', 'The three angles of any triangle add up to…', '180°', '["90°","360°","270°"]', 'So if one corner is 90°, the other two must add up to 90°.', 'approved', '2026-11-19 00:55:17');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (1363, 'original', 'diy-miter', 'Home & DIY', NULL, 'multiple', 'To join two boards in a 90° corner, like a picture frame, each is cut at…', '45°', '["90°","30°","60°"]', 'Two 45° miter cuts add up to the 90° corner.', 'approved', '2026-11-19 00:55:17');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (1364, 'original', 'money-simple-interest', 'Money', NULL, 'multiple', 'Simple interest is paid only on…', 'The original amount', '["The original plus past interest","The interest earned so far","Your highest balance"]', 'Compound interest also earns interest on past interest, which is why it grows faster.', 'approved', '2026-11-19 00:55:17');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (1365, 'original', 'money-compound-wins', 'Money', NULL, 'multiple', 'Same rate, same 20 years. Which earns more?', 'Compound interest', '["Simple interest","They''re equal","Depends on the bank"]', 'Compounding earns interest on interest, so the gap widens every single year.', 'approved', '2026-11-19 00:55:17');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (1366, 'original', 'money-apy', 'Money', NULL, 'multiple', 'Which rate includes the effect of compounding?', 'APY', '["APR","Prime rate","Principal"]', 'APY (annual percentage yield) is what you actually earn in a year with compounding. APR leaves it out.', 'approved', '2026-11-19 00:55:17');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (1367, 'original', 'money-cc-monthly', 'Money', NULL, 'multiple', 'A credit card charges 24% APR. Roughly what is that per month?', '2%', '["24%","4%","0.5%"]', '24% ÷ 12 months = 2% a month, charged on any balance you carry.', 'approved', '2026-11-19 00:55:17');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (1368, 'original', 'money-compounded-monthly', 'Money', NULL, 'multiple', '"Compounded monthly" means interest is added…', '12 times a year', '["Once a year","Every day","Only at the end"]', 'Each month''s interest is added to the balance, and the next month earns interest on it.', 'approved', '2026-11-19 00:55:17');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (1369, 'original', 'kitchen-tbsp-per-cup', 'Kitchen', NULL, 'multiple', 'How many tablespoons are in one cup?', '16', '["8","12","24"]', '1 cup = 16 tbsp, so ¼ cup = 4 tbsp.', 'approved', '2026-11-19 00:55:17');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (1370, 'original', 'kitchen-tsp-per-tbsp', 'Kitchen', NULL, 'multiple', 'How many teaspoons make one tablespoon?', '3', '["2","4","5"]', '3 tsp = 1 tbsp. No tablespoon handy? Use three teaspoons.', 'approved', '2026-11-19 00:55:17');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (1371, 'original', 'kitchen-freezing-f', 'Kitchen', NULL, 'multiple', 'Water freezes at what temperature in °F?', '32°F', '["0°F","40°F","212°F"]', '32°F = 0°C. Water boils at 212°F (100°C) at sea level.', 'approved', '2026-11-19 00:55:17');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (1372, 'original', 'measure-inch-cm', 'Measurement', NULL, 'multiple', 'One inch is how many centimeters?', '2.54', '["1.5","3.25","10"]', '1 in = 2.54 cm exactly. A 30 cm ruler is about 12 inches.', 'approved', '2026-11-19 00:55:17');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (1373, 'original', 'measure-km-mile', 'Measurement', NULL, 'multiple', 'One kilometer is roughly how many miles?', '0.62', '["1.6","0.25","1.0"]', '1 km ≈ 0.62 mi (and 1 mi ≈ 1.6 km). A 5K race is about 3.1 miles.', 'approved', '2026-11-19 00:55:17');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (1374, 'original', 'measure-feet-mile', 'Measurement', NULL, 'multiple', 'How many feet are in a mile?', '5,280', '["1,000","3,280","5,000"]', '5,280 ft = 1 mile. Fun fact: a kilometer is about 3,280 ft.', 'approved', '2026-11-19 00:55:17');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (1375, 'original', 'travel-mpg', 'Travel', NULL, 'multiple', 'You drive 300 miles on 10 gallons. What''s your fuel economy?', '30 mpg', '["3 mpg","25 mpg","35 mpg"]', 'Miles ÷ gallons: 300 ÷ 10 = 30 mpg.', 'approved', '2026-11-19 00:55:17');
