INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (1388, 'original', 'money-rule-72:2', 'Money', NULL, 'multiple', 'At 2% a year, about how many years until your money doubles?', '36 years', '["24 years","18 years","12 years"]', 'Rule of 72: divide 72 by the rate. 72 ÷ 2 = 36 years. It works for inflation and debt too.', 'approved', '2026-11-19 00:55:17');
