INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (1395, 'original', 'diy-pythagoras:6-8-10', 'Home & DIY', NULL, 'multiple', 'Squaring a corner: you mark 6 ft on one wall and 8 ft on the other. What should the diagonal be?', '10 ft', '["14 ft","11 ft","9 ft"]', '6² + 8² = 10² (36 + 64 = 100). A 10 ft diagonal means a true 90° corner.', 'approved', '2026-11-19 00:55:17');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (1396, 'original', 'diy-pythagoras:9-12-15', 'Home & DIY', NULL, 'multiple', 'Squaring a corner: you mark 9 ft on one wall and 12 ft on the other. What should the diagonal be?', '15 ft', '["21 ft","16 ft","14 ft"]', '9² + 12² = 15² (81 + 144 = 225). A 15 ft diagonal means a true 90° corner.', 'approved', '2026-11-19 00:55:17');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (1397, 'original', 'diy-pythagoras:5-12-13', 'Home & DIY', NULL, 'multiple', 'Squaring a corner: you mark 5 ft on one wall and 12 ft on the other. What should the diagonal be?', '13 ft', '["17 ft","14 ft","12 ft"]', '5² + 12² = 13² (25 + 144 = 169). A 13 ft diagonal means a true 90° corner.', 'approved', '2026-11-19 00:55:17');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (1398, 'original', 'diy-pythagoras:8-15-17', 'Home & DIY', NULL, 'multiple', 'Squaring a corner: you mark 8 ft on one wall and 15 ft on the other. What should the diagonal be?', '17 ft', '["23 ft","18 ft","16 ft"]', '8² + 15² = 17² (64 + 225 = 289). A 17 ft diagonal means a true 90° corner.', 'approved', '2026-11-19 00:55:17');
