INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (1414, 'original', 'money-compound-2y:500', 'Money', NULL, 'multiple', '$500 earns 10% a year, compounded yearly. What''s it worth after 2 years?', '$605', '["$600","$550","$650"]', 'Year 1: $500 + 10% = $550. Year 2 earns 10% on that: $605. Simple interest would only reach $600.', 'approved', '2026-11-19 00:55:17');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (1415, 'original', 'money-compound-2y:1000', 'Money', NULL, 'multiple', '$1,000 earns 10% a year, compounded yearly. What''s it worth after 2 years?', '$1,210', '["$1,200","$1,100","$1,300"]', 'Year 1: $1,000 + 10% = $1,100. Year 2 earns 10% on that: $1,210. Simple interest would only reach $1,200.', 'approved', '2026-11-19 00:55:17');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (1416, 'original', 'money-compound-2y:2000', 'Money', NULL, 'multiple', '$2,000 earns 10% a year, compounded yearly. What''s it worth after 2 years?', '$2,420', '["$2,400","$2,200","$2,600"]', 'Year 1: $2,000 + 10% = $2,200. Year 2 earns 10% on that: $2,420. Simple interest would only reach $2,400.', 'approved', '2026-11-19 00:55:17');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (1417, 'original', 'money-compound-2y:5000', 'Money', NULL, 'multiple', '$5,000 earns 10% a year, compounded yearly. What''s it worth after 2 years?', '$6,050', '["$6,000","$5,500","$6,500"]', 'Year 1: $5,000 + 10% = $5,500. Year 2 earns 10% on that: $6,050. Simple interest would only reach $6,000.', 'approved', '2026-11-19 00:55:17');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (1418, 'original', 'kitchen-c-to-f:0', 'Kitchen', NULL, 'multiple', 'What is 0°C in °F?', '32°F', '["42°F","22°F","52°F"]', '°F = °C × 1.8 + 32, so 0 × 1.8 + 32 = 32. Quick estimate: double it and add 30.', 'approved', '2026-11-19 00:55:17');
