INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (4961, 'opentriviaqa', 'aa35fd1a369d283a', 'Science', NULL, 'multiple', 'The carnation is the national flower of this European country.', 'Spain', '["France","Scotland","Germany"]', NULL, 'rejected', '2026-11-19 01:12:54');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (4962, 'opentriviaqa', '85cf7c86e9fe957d', 'Science', NULL, 'multiple', 'To which continent are common daisies native?', 'Europe', '["All of these","North America","Asia"]', NULL, 'rejected', '2026-11-19 01:12:54');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (4963, 'opentriviaqa', '68b9a3b7fabba840', 'Science', NULL, 'multiple', 'According to Greek mythology, Zeus saved one of Asclepius students from his wrath by turning him into this flower.', 'Peony', '["Rose","Forget-me-not","Dahlia"]', NULL, 'rejected', '2026-11-19 01:12:54');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (4964, 'opentriviaqa', 'a7a5ff8ffc536e8c', 'Science', NULL, 'multiple', 'The Lilium plants, commonly known as lilies, are extremely toxic to this animal.', 'Cat', '["Dog","All of these","Sheep"]', NULL, 'approved', '2026-11-19 01:12:54');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (4965, 'original', 'kitchen-poultry-temp', 'Kitchen', NULL, 'multiple', 'What internal temperature makes chicken safe to eat?', '165°F', '["145°F","155°F","125°F"]', 'USDA: cook all poultry, including ground, to 165°F. Check the thickest part with a thermometer.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (4966, 'original', 'kitchen-ground-beef-temp', 'Kitchen', NULL, 'multiple', 'What''s the minimum safe internal temperature for a hamburger?', '160°F', '["145°F","130°F","120°F"]', 'Ground meat needs 160°F because grinding spreads surface bacteria all the way through.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (4967, 'original', 'kitchen-steak-temp', 'Kitchen', NULL, 'multiple', 'Minimum safe temperature for a beef steak or pork chop (plus a 3-minute rest)?', '145°F', '["125°F","135°F","165°F"]', 'Whole cuts of beef, pork, veal, and lamb: 145°F, then rest at least 3 minutes (USDA).', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (4968, 'original', 'kitchen-danger-zone', 'Kitchen', NULL, 'multiple', 'Bacteria multiply fastest in the food "danger zone" between…', '40°F and 140°F', '["0°F and 32°F","140°F and 212°F","-10°F and 20°F"]', 'Keep cold food below 40°F and hot food above 140°F.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (4969, 'original', 'kitchen-two-hour-rule', 'Kitchen', NULL, 'multiple', 'Leftovers should go into the fridge within…', '2 hours', '["6 hours","12 hours","24 hours"]', 'Two hours at room temperature, or just 1 hour if it''s above 90°F (like a summer picnic).', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (4970, 'original', 'kitchen-fridge-temp', 'Kitchen', NULL, 'multiple', 'Your refrigerator should be set at or below…', '40°F', '["50°F","55°F","60°F"]', '40°F or colder slows bacteria. A cheap fridge thermometer tells you for sure.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (4971, 'original', 'kitchen-freezer-temp', 'Kitchen', NULL, 'multiple', 'A freezer should be kept at…', '0°F', '["32°F","20°F","10°F"]', 'At 0°F food stays safe indefinitely. Quality still fades over time, but it won''t spoil.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (4972, 'original', 'kitchen-altitude-boil', 'Kitchen', NULL, 'multiple', 'High up in the mountains, water boils at a ___ temperature.', 'Lower', '["Higher","Same","Random"]', 'Less air pressure means water boils sooner, so pasta and eggs take longer to cook.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (4973, 'original', 'kitchen-stick-butter', 'Kitchen', NULL, 'multiple', 'One stick of butter is how many tablespoons?', '8', '["4","6","16"]', '1 stick = ½ cup = 8 tablespoons = 4 ounces.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (4974, 'original', 'kitchen-cups-pint', 'Kitchen', NULL, 'multiple', 'How many cups are in a pint?', '2', '["4","3","8"]', '2 cups = 1 pint = 16 fl oz. "A pint''s a pound the world around" (roughly, for water).', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (4975, 'original', 'kitchen-cups-quart', 'Kitchen', NULL, 'multiple', 'How many cups are in a quart?', '4', '["2","6","8"]', 'A quart is a "quarter" gallon: 4 cups, or 32 fl oz.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (4976, 'original', 'kitchen-quarts-gallon', 'Kitchen', NULL, 'multiple', 'How many quarts are in a gallon?', '4', '["2","8","16"]', '1 gallon = 4 quarts = 8 pints = 16 cups = 128 fl oz.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (4977, 'original', 'kitchen-oz-pound', 'Kitchen', NULL, 'multiple', 'How many ounces are in a pound?', '16', '["12","10","8"]', '16 oz = 1 lb, so a quarter-pound burger is 4 oz.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (4978, 'original', 'kitchen-kg-pounds', 'Kitchen', NULL, 'multiple', 'One kilogram is about how many pounds?', '2.2', '["1.5","3.3","0.45"]', '1 kg ≈ 2.2 lb, and 1 lb ≈ 454 g (NIST).', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (4979, 'original', 'kitchen-ounce-grams', 'Kitchen', NULL, 'multiple', 'One ounce is about how many grams?', '28', '["10","100","454"]', '1 oz ≈ 28 g. (454 g is a whole pound.)', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (4980, 'original', 'kitchen-cup-ml', 'Kitchen', NULL, 'multiple', 'One US cup is about how many milliliters?', '240', '["100","500","1,000"]', 'NIST: 1 cup ≈ 240 mL, 1 tablespoon ≈ 15 mL, 1 teaspoon ≈ 5 mL.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (4981, 'original', 'kitchen-tbsp-ml', 'Kitchen', NULL, 'multiple', 'One tablespoon is about how many milliliters?', '15', '["5","30","50"]', '1 tbsp ≈ 15 mL and 1 tsp ≈ 5 mL, which is why 3 tsp = 1 tbsp.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (4982, 'original', 'kitchen-oven-350', 'Kitchen', NULL, 'multiple', 'A recipe says 350°F. About what is that in °C?', '175°C', '["120°C","250°C","350°C"]', '350°F ≈ 175–180°C, the most common baking temperature.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (4983, 'original', 'diy-ladder-4-to-1', 'Home & DIY', NULL, 'multiple', 'For a safe ladder angle, move the base out 1 foot for every ___ feet of height.', '4', '["2","6","10"]', 'OSHA''s 4-to-1 rule: the base sits ¼ of the working length away from the wall.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (4984, 'original', 'diy-ladder-3ft-above', 'Home & DIY', NULL, 'multiple', 'A ladder used to climb onto a roof should extend past the edge by at least…', '3 feet', '["6 inches","1 foot","6 feet"]', 'OSHA: at least 3 feet above the landing, so you have something to hold when stepping off.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (4985, 'original', 'diy-ladder-3-points', 'Home & DIY', NULL, 'multiple', 'How many points of contact should you keep while climbing a ladder?', '3', '["1","2","4"]', 'Two hands and a foot, or two feet and a hand, at all times (OSHA).', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (4986, 'original', 'diy-ladder-top-rungs', 'Home & DIY', NULL, 'multiple', 'On a straight or extension ladder, don''t stand on the top ___ rungs.', '3', '["1","5","0"]', 'OSHA says to stay off the top three rungs, where the ladder is least stable.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (4987, 'original', 'diy-2x4-size', 'Home & DIY', NULL, 'multiple', 'A "2×4" board actually measures about…', '1½ × 3½ in.', '["2 × 4 in.","1¾ × 3¾ in.","2½ × 4½ in."]', 'Lumber is named by its rough-cut size, then dried and planed down.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (4988, 'original', 'diy-plywood-sheet', 'Home & DIY', NULL, 'multiple', 'A standard sheet of plywood or drywall is…', '4 × 8 ft', '["3 × 6 ft","4 × 10 ft","5 × 5 ft"]', '4 × 8 ft = 32 sq ft per sheet, and it lines up with 16-inch stud spacing.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (4989, 'original', 'diy-cubic-yard', 'Home & DIY', NULL, 'multiple', 'How many cubic feet are in a cubic yard (of concrete or mulch)?', '27', '["9","3","36"]', '3 ft × 3 ft × 3 ft = 27 cubic feet. Bulk materials are sold by the cubic yard.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (4990, 'original', 'diy-acre', 'Home & DIY', NULL, 'multiple', 'An acre is about how many square feet?', '43,560', '["10,000","5,280","100,000"]', '43,560 sq ft, roughly an American football field without the end zones.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (4991, 'original', 'diy-drain-slope', 'Home & DIY', NULL, 'multiple', 'Household drain pipes typically slope about how much per foot?', '¼ inch', '["1 inch","2 inches","None, they''re level"]', 'About ¼ in. per foot, steep enough to drain but slow enough to carry solids.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (4992, 'original', 'diy-watts-formula', 'Home & DIY', NULL, 'multiple', 'Watts equal volts times…', 'Amps', '["Ohms","Hertz","Joules"]', 'Power (W) = voltage (V) × current (A).', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (4993, 'original', 'diy-15-amp-circuit', 'Home & DIY', NULL, 'multiple', 'A 15-amp, 120-volt household circuit can supply at most about…', '1,800 watts', '["150 watts","500 watts","15,000 watts"]', '120 V × 15 A = 1,800 W. Two space heaters on one circuit can trip it.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (4994, 'original', 'money-up-down-50', 'Money', NULL, 'multiple', 'An investment goes up 50%, then down 50%. Overall you are…', 'Down 25%', '["Even","Up 25%","Down 50%"]', '$100 → $150 → $75. Percent changes don''t cancel out.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (4995, 'original', 'money-30-vs-15-year', 'Money', NULL, 'multiple', 'Same home loan and rate: a 30-year mortgage costs ___ total interest than a 15-year.', 'More', '["Less","About the same","Exactly half"]', 'Lower monthly payments, but you pay interest for twice as long.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (4996, 'original', 'money-percent-of-percent', 'Money', NULL, 'multiple', 'A price is cut 20%, then another 20%. The total discount is…', '36%', '["40%","20%","44%"]', '$100 → $80 → $64. The second 20% comes off the already-lower price.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (4997, 'original', 'nav-north-star', 'Navigation', NULL, 'multiple', 'Which star stays nearly fixed above the North Pole?', 'Polaris', '["Sirius","Vega","Betelgeuse"]', 'Follow the two "pointer" stars at the end of the Big Dipper''s cup to find it.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (4998, 'original', 'nav-noon-sun', 'Navigation', NULL, 'multiple', 'From the US at midday, the sun is roughly due…', 'South', '["North","East","West"]', 'North of the tropics, the midday sun is always in the southern sky.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (4999, 'original', 'nav-time-zone-width', 'Navigation', NULL, 'multiple', 'Each time zone is about how many degrees of longitude wide?', '15°', '["10°","24°","30°"]', '360° ÷ 24 hours = 15° per hour of time.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5000, 'original', 'nav-degree-latitude', 'Navigation', NULL, 'multiple', 'One degree of latitude is roughly how many miles?', '69', '["10","24","360"]', 'About 69 miles (111 km). Handy for reading map grids.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5001, 'original', 'nav-contour-lines', 'Navigation', NULL, 'multiple', 'On a topographic map, contour lines bunched close together mean…', 'Steep ground', '["Flat ground","A river","A road"]', 'Each line is a step in elevation. Lines close together mean a big climb over a short distance.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5002, 'original', 'nav-usgs-scale', 'Navigation', NULL, 'multiple', 'On a standard 1:24,000 USGS topo map, 1 inch equals…', '2,000 feet', '["1 mile","24,000 feet","100 feet"]', '24,000 inches = 2,000 ft. About 2½ inches on the map is a mile.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5003, 'original', 'nav-moss-myth', 'Navigation', NULL, 'multiple', 'Moss growing on trees reliably points…', 'Nowhere: it''s a myth', '["North","South","East"]', 'Moss grows wherever it''s shady and damp. Use the sun, the stars, or a compass instead.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5004, 'original', 'safety-lightning-divide', 'Safety', NULL, 'multiple', 'Count the seconds from lightning to thunder, then divide by ___ to get miles.', '5', '["2","3","10"]', 'Sound travels about a mile every 5 seconds (NOAA). For kilometers, divide by 3.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5005, 'original', 'safety-hear-thunder', 'Safety', NULL, 'multiple', 'If you can hear thunder, you are…', 'Close enough to be struck', '["Safe if it isn''t raining","At least 20 miles away","Safe under a tree"]', 'Thunder carries about 10 miles, and lightning can strike that far out. Go indoors (NWS).', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5006, 'original', 'safety-flood-car', 'Safety', NULL, 'multiple', 'About how much moving floodwater can sweep away most cars?', '1 foot', '["3 feet","5 feet","10 feet"]', 'NWS: 12 inches of moving water can float a car, and 6 inches can knock you down. Turn around, don''t drown.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5007, 'original', 'safety-cpr-rate', 'Safety', NULL, 'multiple', 'Hands-only CPR: about how many chest compressions per minute?', '100–120', '["30–40","60–80","150–180"]', 'About the beat of "Stayin'' Alive" (American Heart Association).', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5008, 'original', 'safety-cpr-depth', 'Safety', NULL, 'multiple', 'In adult CPR, how deep should each chest compression be?', 'About 2 inches', '["About ½ inch","About 4 inches","About 6 inches"]', 'Push hard and fast, at least 2 in. deep, and let the chest come all the way back up.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5009, 'original', 'safety-heart-rate', 'Safety', NULL, 'multiple', 'A normal adult resting heart rate is…', '60–100 bpm', '["30–50 bpm","110–150 bpm","150–200 bpm"]', 'Fit athletes can sit lower. Count your pulse for 15 seconds and multiply by 4.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5010, 'original', 'safety-fever', 'Safety', NULL, 'multiple', 'A fever generally starts at about…', '100.4°F', '["98.6°F","99.0°F","104°F"]', '98.6°F is the classic "normal". 100.4°F (38°C) is the usual fever line.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5011, 'original', 'measure-meter-feet', 'Measurement', NULL, 'multiple', 'One meter is about how many feet?', '3.3', '["1.6","2.5","10"]', '1 m ≈ 3.28 ft, a little longer than a yard.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5012, 'original', 'measure-liter-quart', 'Measurement', NULL, 'multiple', 'A liter is just a little more than a…', 'Quart', '["Cup","Pint","Gallon"]', '1 L ≈ 1.06 quarts, so a 2-liter bottle is about half a gallon.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5013, 'original', 'measure-yard-inches', 'Measurement', NULL, 'multiple', 'How many inches are in a yard?', '36', '["12","24","48"]', '3 feet × 12 inches = 36 inches.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5014, 'original', 'measure-ton-pounds', 'Measurement', NULL, 'multiple', 'A US (short) ton is how many pounds?', '2,000', '["1,000","2,240","5,000"]', '2,000 lb. The British "long" ton is 2,240 lb.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5015, 'original', 'measure-pizza-area', 'Measurement', NULL, 'multiple', 'A 16-inch pizza has how much more area than an 8-inch pizza?', '4 times', '["2 times","3 times","8 times"]', 'Area grows with the square: double the width, four times the pizza (πr²).', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5016, 'original', 'safety-lightning-distance:5', 'Safety', NULL, 'multiple', 'You count 5 seconds between the flash and the thunder. How far away was the lightning?', '1 mile', '["2 miles","5 miles","½ mile"]', 'Divide by 5: 5 ÷ 5 = 1. Anything under 10 miles is close enough to strike you.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5017, 'original', 'safety-lightning-distance:10', 'Safety', NULL, 'multiple', 'You count 10 seconds between the flash and the thunder. How far away was the lightning?', '2 miles', '["4 miles","10 miles","1 mile"]', 'Divide by 5: 10 ÷ 5 = 2. Anything under 10 miles is close enough to strike you.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5018, 'original', 'safety-lightning-distance:15', 'Safety', NULL, 'multiple', 'You count 15 seconds between the flash and the thunder. How far away was the lightning?', '3 miles', '["6 miles","15 miles","1½ miles"]', 'Divide by 5: 15 ÷ 5 = 3. Anything under 10 miles is close enough to strike you.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5019, 'original', 'safety-lightning-distance:20', 'Safety', NULL, 'multiple', 'You count 20 seconds between the flash and the thunder. How far away was the lightning?', '4 miles', '["8 miles","20 miles","2 miles"]', 'Divide by 5: 20 ÷ 5 = 4. Anything under 10 miles is close enough to strike you.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5020, 'original', 'safety-lightning-distance:30', 'Safety', NULL, 'multiple', 'You count 30 seconds between the flash and the thunder. How far away was the lightning?', '6 miles', '["12 miles","30 miles","3 miles"]', 'Divide by 5: 30 ÷ 5 = 6. Anything under 10 miles is close enough to strike you.', 'approved', '2026-11-19 01:18:25');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5021, 'original', 'safety-lightning-distance:40', 'Safety', NULL, 'multiple', 'You count 40 seconds between the flash and the thunder. How far away was the lightning?', '8 miles', '["16 miles","40 miles","4 miles"]', 'Divide by 5: 40 ÷ 5 = 8. Anything under 10 miles is close enough to strike you.', 'approved', '2026-11-19 01:18:25');
