INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5057, 'original', 'math-coin-streak', 'Math', NULL, 'multiple', 'A fair coin lands heads 5 times in a row. What''s the chance the next flip is heads?', '50%', '["Less than 50%","More than 50%","Almost 0%"]', 'Coins have no memory. Believing a streak changes the odds is called the gambler''s fallacy.', 'approved', '2026-11-19 01:22:23');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5058, 'original', 'math-die-six', 'Math', NULL, 'multiple', 'What''s the chance of rolling a 6 on one regular die?', '1 in 6', '["1 in 3","1 in 12","1 in 2"]', 'Six equally likely faces, one of them a 6.', 'approved', '2026-11-19 01:22:23');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5059, 'original', 'math-card-heart', 'Math', NULL, 'multiple', 'Draw one card from a shuffled deck. Chance it''s a heart?', '1 in 4', '["1 in 13","1 in 2","1 in 52"]', '13 hearts out of 52 cards = 1/4.', 'approved', '2026-11-19 01:22:23');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5060, 'original', 'math-two-heads', 'Math', NULL, 'multiple', 'Flip two coins. What''s the chance both land heads?', '1 in 4', '["1 in 2","1 in 3","1 in 8"]', 'HH, HT, TH, TT: one outcome out of four.', 'approved', '2026-11-19 01:22:23');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5061, 'original', 'math-dice-seven', 'Math', NULL, 'multiple', 'Which total is most likely when you roll two dice?', '7', '["12","2","10"]', 'Six combinations make 7 (1+6, 2+5, 3+4…). Only one makes 2 or 12.', 'approved', '2026-11-19 01:22:23');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5062, 'original', 'math-median-outlier', 'Math', NULL, 'multiple', 'A billionaire moves into a small town. Which barely changes?', 'Median income', '["Average (mean) income","Total income","Highest income"]', 'One huge value drags the mean way up, but the middle value (median) hardly moves.', 'approved', '2026-11-19 01:22:23');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5063, 'original', 'math-mode-meaning', 'Math', NULL, 'multiple', 'In a list of numbers, the "mode" is…', 'The most common value', '["The middle value","The average","The biggest minus smallest"]', 'Mode = most frequent, median = middle, mean = average, range = max − min.', 'approved', '2026-11-19 01:22:23');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5064, 'original', 'math-order-of-ops', 'Math', NULL, 'multiple', 'What is 2 + 3 × 4?', '14', '["20","24","9"]', 'Multiply before adding: 3 × 4 = 12, then 2 + 12 = 14.', 'approved', '2026-11-19 01:22:23');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5065, 'original', 'math-negative-temp', 'Math', NULL, 'multiple', 'It''s −5°F and warms up 12 degrees. What''s the temperature now?', '7°F', '["17°F","−17°F","−7°F"]', '−5 + 12 = 7. Count up 5 to reach zero, then 7 more.', 'approved', '2026-11-19 01:22:23');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5066, 'original', 'math-estimate-19x21', 'Math', NULL, 'multiple', 'Quick estimate: 19 × 21 is closest to…', '400', '["200","4,000","40"]', 'Round to 20 × 20 = 400. (The exact answer is 399.)', 'approved', '2026-11-19 01:22:23');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5067, 'original', 'math-eighth-percent', 'Math', NULL, 'multiple', '⅛ written as a percent is…', '12.5%', '["8%","18%","25%"]', '1 ÷ 8 = 0.125 = 12.5%. Handy: ⅛ cup is 2 tablespoons.', 'approved', '2026-11-19 01:22:23');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5068, 'original', 'math-three-quarters', 'Math', NULL, 'multiple', '0.75 written as a fraction is…', '¾', '["⅔","⅞","7/5"]', '75 cents is three quarters of a dollar.', 'approved', '2026-11-19 01:22:23');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5069, 'original', 'math-half-plus-quarter', 'Math', NULL, 'multiple', '½ cup + ¼ cup = ?', '¾ cup', '["⅔ cup","1 cup","2/6 cup"]', '½ = 2/4, and 2/4 + 1/4 = 3/4.', 'approved', '2026-11-19 01:22:23');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5070, 'original', 'math-concrete-ratio', 'Math', NULL, 'multiple', 'A 1:2:3 concrete mix (cement : sand : gravel) uses 2 buckets of cement. How much sand?', '4 buckets', '["2 buckets","3 buckets","6 buckets"]', 'Sand is twice the cement in a 1:2:3 mix, so 2 × 2 = 4.', 'approved', '2026-11-19 01:22:23');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5071, 'original', 'math-wheel-circumference', 'Math', NULL, 'multiple', 'A wheel 10 inches across rolls one full turn. About how far does it go?', '31 inches', '["10 inches","20 inches","100 inches"]', 'Circumference = π × diameter ≈ 3.14 × 10 = 31.4 inches.', 'approved', '2026-11-19 01:22:23');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5072, 'original', 'math-circle-area', 'Math', NULL, 'multiple', 'About what''s the area of a circle with a 10-ft radius?', '314 sq ft', '["31 sq ft","100 sq ft","1,000 sq ft"]', 'Area = π × r² ≈ 3.14 × 100 = 314 sq ft.', 'approved', '2026-11-19 01:22:23');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5073, 'original', 'math-double-sides-area', 'Math', NULL, 'multiple', 'Double the length and width of a garden bed. Its area becomes…', '4 times bigger', '["2 times bigger","3 times bigger","8 times bigger"]', '2 × 2 = 4. Double all three dimensions of a box and the volume is 8 times bigger.', 'approved', '2026-11-19 01:22:23');
