INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5079, 'original', 'math-percent-of:30-50', 'Math', NULL, 'multiple', 'What''s 30% of $50?', '$15', '["$30","$20","$35"]', '10% is $5, so 30% is 3 × that = $15.', 'approved', '2026-11-19 01:22:23');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5080, 'original', 'math-percent-of:5-240', 'Math', NULL, 'multiple', 'What''s 5% of $240?', '$12', '["$24","$17","$228"]', '10% is $24, and 5% is half that: $12.', 'approved', '2026-11-19 01:22:23');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5081, 'original', 'math-percent-of:75-40', 'Math', NULL, 'multiple', 'What''s 75% of $40?', '$30', '["$60","$35","$10"]', '75% is three quarters: $10 × 3 = $30.', 'approved', '2026-11-19 01:22:23');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5082, 'original', 'math-median:3-9-4-7-5', 'Math', NULL, 'multiple', 'What''s the median of 3, 9, 4, 7, 5?', '5', '["5.6","4","6"]', 'Sort them (3, 4, 5, 7, 9) and take the middle one: 5.', 'approved', '2026-11-19 01:22:23');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5083, 'original', 'math-median:10-2-8-6-1', 'Math', NULL, 'multiple', 'What''s the median of 10, 2, 8, 6, 1?', '6', '["5.4","8","9"]', 'Sort them (1, 2, 6, 8, 10) and take the middle one: 6.', 'approved', '2026-11-19 01:22:23');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5084, 'original', 'math-median:12-15-11-30-14', 'Math', NULL, 'multiple', 'What''s the median of 12, 15, 11, 30, 14?', '14', '["16.4","11","19"]', 'Sort them (11, 12, 14, 15, 30) and take the middle one: 14.', 'approved', '2026-11-19 01:22:23');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5085, 'original', 'math-median:5-1-9-3-7', 'Math', NULL, 'multiple', 'What''s the median of 5, 1, 9, 3, 7?', '5', '["9","8","6"]', 'Sort them (1, 3, 5, 7, 9) and take the middle one: 5.', 'approved', '2026-11-19 01:22:23');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5086, 'original', 'math-mean:2-4-6', 'Math', NULL, 'multiple', 'What''s the average of 2, 4, 6?', '4', '["12","5","3"]', 'Add them up (12) and divide by how many there are (3): 4.', 'approved', '2026-11-19 01:22:23');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5087, 'original', 'math-mean:10-20-30-40', 'Math', NULL, 'multiple', 'What''s the average of 10, 20, 30, 40?', '25', '["100","26","24"]', 'Add them up (100) and divide by how many there are (4): 25.', 'approved', '2026-11-19 01:22:23');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5088, 'original', 'math-mean:5-5-8', 'Math', NULL, 'multiple', 'What''s the average of 5, 5, 8?', '6', '["18","7","5"]', 'Add them up (18) and divide by how many there are (3): 6.', 'approved', '2026-11-19 01:22:23');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5089, 'original', 'math-mean:80-90-100', 'Math', NULL, 'multiple', 'What''s the average of 80, 90, 100?', '90', '["270","91","89"]', 'Add them up (270) and divide by how many there are (3): 90.', 'approved', '2026-11-19 01:22:23');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5090, 'original', 'math-mean:1-2-3-4-5', 'Math', NULL, 'multiple', 'What''s the average of 1, 2, 3, 4, 5?', '3', '["15","4","2"]', 'Add them up (15) and divide by how many there are (5): 3.', 'approved', '2026-11-19 01:22:23');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5091, 'original', 'money-simple-interest:1000-5-3', 'Money', NULL, 'multiple', '$1,000 at 5% simple interest for 3 years earns how much interest?', '$150', '["$50","$300","$1,150"]', 'Interest = principal × rate × time: $1,000 × 5% × 3 = $150.', 'approved', '2026-11-19 01:22:23');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5092, 'original', 'money-simple-interest:2000-4-2', 'Money', NULL, 'multiple', '$2,000 at 4% simple interest for 2 years earns how much interest?', '$160', '["$80","$320","$2,160"]', 'Interest = principal × rate × time: $2,000 × 4% × 2 = $160.', 'approved', '2026-11-19 01:22:23');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5093, 'original', 'money-simple-interest:500-10-2', 'Money', NULL, 'multiple', '$500 at 10% simple interest for 2 years earns how much interest?', '$100', '["$50","$200","$600"]', 'Interest = principal × rate × time: $500 × 10% × 2 = $100.', 'approved', '2026-11-19 01:22:23');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5094, 'original', 'money-simple-interest:5000-3-4', 'Money', NULL, 'multiple', '$5,000 at 3% simple interest for 4 years earns how much interest?', '$600', '["$150","$1,200","$5,600"]', 'Interest = principal × rate × time: $5,000 × 3% × 4 = $600.', 'approved', '2026-11-19 01:22:23');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5095, 'original', 'math-map-scale:5-3', 'Math', NULL, 'multiple', 'A map''s scale is 1 inch = 5 miles. Two towns are 3 inches apart. How far is that?', '15 miles', '["8 miles","30 miles","7.5 miles"]', '3 × 5 = 15 miles.', 'approved', '2026-11-19 01:22:23');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5096, 'original', 'math-map-scale:10-2.5', 'Math', NULL, 'multiple', 'A map''s scale is 1 inch = 10 miles. Two towns are 2½ inches apart. How far is that?', '25 miles', '["12.5 miles","50 miles","35 miles"]', '2½ × 10 = 25 miles.', 'approved', '2026-11-19 01:22:23');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5097, 'original', 'math-map-scale:2-7', 'Math', NULL, 'multiple', 'A map''s scale is 1 inch = 2 miles. Two towns are 7 inches apart. How far is that?', '14 miles', '["9 miles","28 miles","7 miles"]', '7 × 2 = 14 miles.', 'approved', '2026-11-19 01:22:23');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5098, 'original', 'math-map-scale:25-4', 'Math', NULL, 'multiple', 'A map''s scale is 1 inch = 25 miles. Two towns are 4 inches apart. How far is that?', '100 miles', '["29 miles","200 miles","50 miles"]', '4 × 25 = 100 miles.', 'approved', '2026-11-19 01:22:23');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5099, 'original', 'math-map-scale:50-1.5', 'Math', NULL, 'multiple', 'A map''s scale is 1 inch = 50 miles. Two towns are 1½ inches apart. How far is that?', '75 miles', '["51.5 miles","150 miles","37.5 miles"]', '1½ × 50 = 75 miles.', 'approved', '2026-11-19 01:22:23');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5100, 'original', 'math-add-fractions:0', 'Math', NULL, 'multiple', '½ + ⅓ = ?', '⅚', '["⅖","⅔","1"]', 'Common denominator 6: 3/6 + 2/6 = 5/6.', 'approved', '2026-11-19 01:22:23');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5101, 'original', 'math-add-fractions:1', 'Math', NULL, 'multiple', '¼ + ⅛ = ?', '⅜', '["2/12","½","⅕"]', '¼ = 2/8, so 2/8 + 1/8 = 3/8.', 'approved', '2026-11-19 01:22:23');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5102, 'original', 'math-add-fractions:2', 'Math', NULL, 'multiple', '⅔ + ⅓ = ?', '1', '["¾","3/6","1⅓"]', 'Same denominator: 2/3 + 1/3 = 3/3 = 1.', 'approved', '2026-11-19 01:22:23');
INSERT INTO questions (id, source, source_ref, category, difficulty, type, prompt, correct, incorrect, explanation, status, created_at) VALUES (5103, 'original', 'math-add-fractions:3', 'Math', NULL, 'multiple', '¾ + ½ = ?', '1¼', '["1","4/6","1½"]', '½ = 2/4, so 3/4 + 2/4 = 5/4 = 1¼.', 'approved', '2026-11-19 01:22:23');
